// H1: cambios en las reglas del firewall UFW del host (lee auth.log vía Loki).
// Los cambios de reglas quedan en auth.log como: sudo: <usuario> : ... ; COMMAND=/usr/sbin/ufw allow 5432/tcp
// (no aparecen en ufw.log, que solo guarda tráfico bloqueado/permitido).
// La anti-repetición (mismo código y detalle en 10 min) la hace Enviar_Alerta.
const resp = $input.first().json || {};
const streams = (resp.data && resp.data.result) || [];

// Solo comandos que CAMBIAN reglas (ufw status / show / version no alertan)
const MUTANTES = /ufw\s+(?:--force\s+)?(allow|deny|reject|limit|delete|insert|prepend|route|enable|disable|reset|default|reload|logging)\b/i;
// Acciones que abren o debilitan el firewall → CRÍTICA; el resto → ADVERTENCIA
const ABRE = /^(allow|insert|prepend|disable|reset|route)$/i;

const vistos = new Set();
const alertas = [];
for (const s of streams) {
  for (const [ts, linea] of (s.values || [])) {
    const clave = ts + linea;
    if (vistos.has(clave)) continue;
    vistos.add(clave);
    const m = String(linea).match(/sudo(?:\[\d+\])?:\s+(\S+)\s+:.*?COMMAND=(.*)$/);
    if (!m) continue;
    const usuario = m[1];
    const cmd = m[2].trim();
    if (!MUTANTES.test(cmd)) continue;

    const verbo = (cmd.match(/ufw\s+(?:--force\s+)?(\w+)/i) || [])[1] || '';
    const critica = ABRE.test(verbo) || /default\s+allow/i.test(cmd);
    const ms = Number(String(ts).slice(0, 13));           // ns → ms
    const hora = new Date(ms).toLocaleString('sv-SE', { timeZone: 'America/Costa_Rica' });
    const postgres = /\b5432\b/.test(cmd) ? ' (puerto de PostgreSQL)' : '';

    alertas.push({ json: {
      codigo: 'H1',
      severidad: critica ? 'CRÍTICA' : 'ADVERTENCIA',
      tipo: 'Cambio en reglas del firewall UFW',
      tabla: 'N/A (firewall UFW del host)',
      detalle: `${usuario} ejecutó "${cmd.replace(/^\/usr\/sbin\/ufw/, 'sudo ufw')}"${postgres} a las ${hora}`,
      query: 'Loki {job="auth"} |~ "COMMAND=/usr/sbin/ufw"',
      usuario,
      accion: 'Si no fue autorizado, revertir la regla (sudo ufw delete ...) y revisar quién inició sesión (last, /var/log/auth.log).'
    }});
  }
}
return alertas;
